def generate(seed):
    r = random.Random(seed)
    for _ in range(1500):
        W = r.randint(32, 42)
        K = r.choice((3, 3, 4))                       # how many rows of drops fit under a cloud
        S = []
        x = r.randint(1, 2)
        while True:
            w = r.randint(3, 5)
            if x + w > W - 1:
                break
            # a shower either reaches the ground (K rows of drops) or stops in the air
            S.append((x, x + w, K if r.random() < 0.45 else r.randint(1, K - 1)))
            x += w + r.randint(3, 5)                  # >= 3 dry columns between showers
        if not (5 <= len(S) <= 7):
            continue
        land = [s for s in S if s[2] == K]
        if not (2 <= len(land) <= 3) or len(S) - len(land) < 2:
            continue
        pos = []
        i = 1
        while i <= W - 2:
            if r.random() < 0.55:
                pos.append(i)
                i += 2
            else:
                i += 1
        if not (9 <= len(pos) <= 15):
            continue
        t = {i: r.choice("*Y") for i in pos}
        v = [*t.values()]
        if v.count("*") < 2 or v.count("Y") < 2:
            continue
        g = "".join(t.get(i, "_") for i in range(W))
        b = ["."] * W
        a = ["."] * W
        for u, e, l in S:
            for i in range(u, e):
                a[i] = "'"
                if l == K:
                    b[i] = "'"
        b = "".join(b)
        a = "".join(a)
        L = [i for i in pos if b[i] != "'" and "'" in b[max(0, i - 1):i + 2]]
        n = len(L)
        wet = [i for i in pos if b[i] == "'"]
        dry = [i for i in pos if b[i] != "'"]
        far = [i for i in dry if a[i] != "'" and "'" not in a[max(0, i - 1):i + 2]]
        gh = [i for i in dry if i not in L and a[i] != "'" and "'" in a[max(0, i - 1):i + 2]]
        und = [i for i in pos if a[i] == "'" and b[i] != "'"]
        if n > 4 or not wet or not far or not und:
            continue
        if n in (len(wet), len(dry)):        # kill "how many got rained on / stayed dry"
            continue
        if len(gh) < 2 and r.random() < 0.85:  # upright plants beside rain that never lands
            continue
        if n == 0 and r.random() > 0.55:     # the foothold, held near 12 %
            continue
        c = ["."] * W
        for u, e, l in S:
            c[u] = "("
            c[e - 1] = ")"
            for i in range(u + 1, e - 1):
                c[i] = "~"
        rows = []
        for j in range(1, K + 1):
            q = ["."] * W
            for u, e, l in S:
                if l >= j:
                    for i in range(u, e):
                        q[i] = "'"
            rows.append("".join(q))
        return "\n".join(["".join(c)] + rows + [g, "%d lean" % n])
