    g = L[-2]
    b = L[-3]
    o = ""
    for i, q in enumerate(g):
        if q in "*Y" and b[i] != "'" and "'" in b[max(0, i - 1):i + 2]:
            o += "\\" if b[i - 1] == "'" else "/"      # the plant leans towards the rain
